new_declarations.declaration:
thing Water
    "An individuated body of water-dominated environmental material under a stated observational boundary convention; the main-constituent criterion remains to be articulated."
    is physical:MaterialBody;

thing SubsurfaceWater
    "Water material below the ground surface, without restricting it to the saturated zone."
    is earth:Water;

thing Groundwater
    "Subsurface water occupying the saturated zone, individuated under a stated hydrogeological convention."
    is earth:SubsurfaceWater;

thing SurfaceWater
    "Water material present in surface-water settings such as rivers and lakes, individuated under a stated hydrological convention."
    is earth:Water;

thing Seawater
    "Marine water material, individuated under a stated oceanographic convention."
    is earth:Water;

functional directed relationship TransfersWaterTo
    "Observed water transfer from an identified donor material water body to an identified recipient material water body."
    links earth:Water to earth:Water;
